def minCost(nums: list[int], cost: list[int]) -> int:
    pairs = sorted(zip(nums, cost))
    total_cost = sum(cost)
    median = 0
    cum = 0
    for x, c in pairs:
        cum += c
        if cum >= (total_cost + 1) // 2:
            median = x
            break
    return sum(abs(x - median) * c for x, c in zip(nums, cost))

